mapper.select:
SELECT DISTINCT CAST(DATE_FORMAT(visited_at, '%Y-%m-%d %H:00:00') AS DATETIME) AS bucket_start FROM
post_view_log page_view_log
WHERE visited_at < #{cutoff} ORDER BY bucket_start ASC LIMIT #{maxBuckets}

SELECT bucket_start, archived_row_count
FROM view_log_archive_bucket
WHERE source = #{source.value}
  AND bucket_start = #{bucketStart}

SELECT COUNT(*)
FROM

    post_view_log
    page_view_log

WHERE visited_at >= #{bucketStart}
  AND visited_at < #{bucketEnd}

mapper.delete:
DELETE FROM

    post_view_log
    page_view_log

WHERE visited_at >= #{bucketStart}
  AND visited_at < #{bucketEnd}

mapper.update:
UPDATE view_log_archive_bucket
SET archived_at = NOW(), archived_row_count = archived_row_count + #{deletedRows}
WHERE source = #{source.value}
  AND bucket_start = #{bucketStart}
